package cn.balltv.portal;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;
public class TiantianSourceTest {
 JSONObject room()throws Exception{return new JSONObject("{uid:81,id:623,islive:1,type:0,title:'甲VS乙',pull:'https://example.org/live.m3u8?txSecret=test',joinMap:{cls:{name:'篮球'},schedule:{id:99,teamNamea:'甲',teamNameb:'乙',beginTime:'2026-01-01 15:00:00',status:1,scorea:20,scoreb:21},room:{name:'主播'}}}");}
 @Test public void anonymousRequestMatchesIndependentNodeCryptoVector()throws Exception{assertEquals("1794219760-BdoRG89IqeBFTR2P%2FBv4ojofkqz7QY0gn82gtgs3%2FaU%3D",TiantianSource.verify("/api?method=listUsersLive&random=0.5",1794219760L));assertEquals("tt,3,1000000,tt-pc,,1794219760,fc5cf4e3a471dd55ffffa32c5060a902b3f0f32aee4965b2ca11e9c1a96c657a",TiantianSource.anonymousHash(1794219760L));}
 @Test public void liveFreeSportsOnly()throws Exception{assertTrue(TiantianSource.allowed(room()));for(String key:new String[]{"hide","isvideo","type"})assertFalse(TiantianSource.allowed(room().put(key,1)));assertFalse(TiantianSource.allowed(room().put("typeVal","password")));assertFalse(TiantianSource.allowed(room().put("islive",0)));assertFalse(TiantianSource.allowed(room().put("title","充值福利")));assertFalse(TiantianSource.allowed(room().put("title","比赛录播")));}
 @Test public void combinesVerifiedMatchRoomsWithoutPersistingMediaToken()throws Exception{List<Feeds.Match> matches=TiantianSource.parse(new JSONArray().put(room()).put(room().put("uid",82).put("id",624)),"");assertEquals(1,matches.size());assertFalse(matches.get(0).estimated);assertEquals("甲",matches.get(0).home);assertEquals(2,matches.get(0).raw.getJSONObject("extra").getJSONArray("rooms").length());assertFalse(matches.get(0).raw.toString().contains("txSecret"));}
 @Test public void unrelatedAndFutureMatchMetadataDoesNotCauseFalseMerge()throws Exception{JSONObject r=room();r.getJSONObject("joinMap").getJSONObject("schedule").put("teamNamea","丙");assertTrue(TiantianSource.parse(new JSONArray().put(r),"").get(0).estimated);r=room();r.getJSONObject("joinMap").getJSONObject("schedule").put("beginTime","2099-01-01 15:00:00");List<Feeds.Match> future=TiantianSource.parse(new JSONArray().put(r),"");assertEquals(0,LiveState.admit(future,System.currentTimeMillis()).size());}
 @Test public void remoteConfigIsDataOnlyAndRejectsInvalidFormat()throws Exception{byte[] bytes=new byte[64];byte[] json="{\"host\":\"https://example.org\"}".getBytes("UTF-8");System.arraycopy(json,0,bytes,0,json.length);byte[] key={80,(byte)150,34,102,112,121,96,102,49,112,104,(byte)128,51,24,40,102};Cipher c=Cipher.getInstance("AES/ECB/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"));StringBuilder hex=new StringBuilder();for(byte b:c.doFinal(bytes))hex.append(String.format(Locale.US,"%02x",b&255));assertEquals("https://example.org",TiantianSource.decodeConfig(hex.toString()).getString("host"));try{TiantianSource.decodeConfig("<script>bad()</script>");fail();}catch(java.io.IOException expected){}}
}
